#!/usr/bin/env node
/**
 * install-trees.mjs — copy the bake-trees.mjs output into assets/pack/models and register it.
 * @doc Run after `node tools/gen/trees/bake-trees.mjs`. Writes models/<species>_lod<n>.bin and one manifest
 *   record each (licence CC0, source `generated:` so a bake-synthetic never prunes them); then run
 *   `node tools/gen/assets.mjs credits` for CREDITS.md. Idempotent. The geometry is generated by this repo
 *   (ez-tree is the MIT builder it drives).
 * @skill asset-pack
 *
 *   node tools/gen/trees/install-trees.mjs
 */
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { LOD_CAPS, SPECIES } from "./caps.mjs";

const require = createRequire(import.meta.url);
const { parseModel, PACK } = require("../../lib/pack-assets.cjs");
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../..");
const SRC = path.join(ROOT, "artifacts", "trees");
const MANIFEST = path.join(PACK, "manifest.json");

const m = JSON.parse(fs.readFileSync(MANIFEST, "utf8"));
m.models = m.models || {};
fs.mkdirSync(path.join(PACK, "models"), { recursive: true });
for (const sp of SPECIES) for (const lod of [0, 1]) {
  const id = `${sp}_lod${lod}`;
  const buf = fs.readFileSync(path.join(SRC, `${id}.bin`));
  const mesh = parseModel(buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength));
  const tris = mesh.idx.length / 3, cap = LOD_CAPS[sp][`lod${lod}`];
  if (tris > cap) throw new Error(`${id}: ${tris} tris over cap ${cap}`);
  const p = mesh.pos;
  const lo = [1e9, 1e9, 1e9], hi = [-1e9, -1e9, -1e9];
  for (let i = 0; i < p.length; i += 3) for (let a = 0; a < 3; a++) {
    lo[a] = Math.min(lo[a], p[i + a]); hi[a] = Math.max(hi[a], p[i + a]);
  }
  fs.writeFileSync(path.join(PACK, "models", `${id}.bin`), buf);
  m.models[id] = {
    file: `models/${id}.bin`, verts: p.length / 3, tris, mat: "FOLIAGE",
    sizeM: [0, 1, 2].map((a) => +(hi[a] - lo[a]).toFixed(2)),
    source: "generated:tools/gen/trees/bake-trees.mjs", licence: "CC0", author: "Apex 26",
    md5: crypto.createHash("md5").update(buf).digest("hex"),
  };
  console.log(`${id}: ${tris} tris / cap ${cap}`);
}
fs.writeFileSync(MANIFEST, JSON.stringify(m, null, 2) + "\n");
